mapper.select:
SELECT , p.category_name as parentName FROM product_category c LEFT JOIN product_category p ON c.parent_id = p.category_id
AND c.category_id = #{categoryId}
AND c.category_name LIKE CONCAT('%', #{categoryName}, '%')
AND c.description LIKE CONCAT('%', #{description}, '%')
AND c.parent_id = #{parentId}
AND c.status = #{status}
ORDER BY c.category_id ASC

mapper.insert:
INSERT INTO product_category (
    category_name, description, parent_id, status, create_time, update_time
) VALUES (
    #{categoryName}, #{description}, #{parentId}, #{status}, #{createTime}, #{updateTime}
)
